flow.set("invinfo_rpc_response_topic", msg.rpcResponseTopic);
flow.set("invinfo_part1", null);
flow.set("invinfo_part2", null);

return msg;

msg.readGroup = "part1";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 0,
    quantity: 10
};
return msg;

msg.readGroup = "part2";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 10,
    quantity: 10
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data)) {
    node.error("Invalid response for " + msg.readGroup);
    return null;
}

const group = msg.readGroup;

if (group === "part1") {
    flow.set("invinfo_part1", data);
} else if (group === "part2") {
    flow.set("invinfo_part2", data);
}

// Check if all parts received
const part1 = flow.get("invinfo_part1");
const part2 = flow.get("invinfo_part2");

if (!part1 || !part2) {
    return null; // Wait for other parts
}

// Combine all data
msg.combinedData = [...part1, ...part2];
return msg;

const data = msg.combinedData;

if (!Array.isArray(data) || data.length < 20) {
    node.error("Invalid combined data: " + data.length + " registers");
    return null;
}

// Clear flow context
flow.set("invinfo_part1", null);
flow.set("invinfo_part2", null);

// Helper: Parse ASCII from packed register (2 chars per register)
function parseAsciiChar(val, high) {
    const byte = high ? ((val >> 8) & 0xFF) : (val & 0xFF);
    if (byte >= 0x20 && byte <= 0x7E) {
        return String.fromCharCode(byte);
    }
    return '';
}

// Helper: Parse Serial Number from registers 003-007 (10 ASCII chars)
function parseSerialNumber(regs) {
    let sn = '';
    for (let i = 0; i < 5; i++) {
        sn += parseAsciiChar(regs[i], true);  // High byte first
        sn += parseAsciiChar(regs[i], false); // Low byte second
    }
    return sn.trim();
}

// Helper: Parse device type
function parseDeviceType(val) {
    switch(val) {
        case 0x0200: return "String Inverter";
        case 0x0300: return "Single-phase Storage";
        case 0x0400: return "Micro Inverter";
        case 0x0500: return "Three-phase Storage";
        default: return "Unknown (0x" + val.toString(16) + ")";
    }
}

// Helper: Parse protocol version
function parseProtocolVersion(val) {
    const major = (val >> 8) & 0xFF;
    const minor = val & 0xFF;
    return major + "." + minor;
}

// Helper: Parse rated power from two registers (0.1W scale)
function parseRatedPower(low, high) {
    const combined = (high << 16) | low;
    return combined * 0.1; // Returns in Watts
}

// Helper: Parse MPPT and phases
function parseMpptPhases(val) {
    const mppt = (val >> 8) & 0xFF;
    const phases = val & 0xFF;
    return { mpptCount: mppt, phaseCount: phases };
}

// Helper: Parse grid voltage rating
function parseGridVoltage(val) {
    switch(val) {
        case 0: return "127/220V";
        case 1: return "220/380V";
        default: return "Unknown (" + val + ")";
    }
}

// Helper: Parse safety/battery type
function parseSafetyType(val) {
    if (val < 3) return "48V Battery";
    if (val === 3) return "24V Battery";
    return "Unknown (" + val + ")";
}

// Parse all registers
const deviceType = parseDeviceType(data[0]);           // 000
const modbusAddress = data[1];                          // 001
const protocolVersion = parseProtocolVersion(data[2]); // 002
const serialNumber = parseSerialNumber(data.slice(3, 8)); // 003-007
const ratedPowerClass = data[8];                        // 008
const chipType = data[9];                               // 009
const commBoardFwField1 = data[10];                     // 010
const commBoardFwField2 = data[11];                     // 011
const ctrlBoardAuxFw = data[12];                        // 012
const ctrlBoardFw = data[13];                           // 013
const commBoardFw = data[14];                           // 014
const safetyType = parseSafetyType(data[15]);          // 015
const ratedPowerW = parseRatedPower(data[16], data[17]); // 016-017
const mpptPhases = parseMpptPhases(data[18]);          // 018
const gridVoltageRating = parseGridVoltage(data[19]);  // 019

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const state = {
    kind: "InverterInfoState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,

    deviceType: deviceType,
    deviceTypeCode: data[0],
    modbusAddress: modbusAddress,
    protocolVersion: protocolVersion,
    serialNumber: serialNumber,

    ratedPowerW: ratedPowerW,
    ratedPowerKw: Math.round(ratedPowerW / 100) / 10,

    mpptCount: mpptPhases.mpptCount,
    phaseCount: mpptPhases.phaseCount,

    gridVoltageRating: gridVoltageRating,
    safetyType: safetyType,

    firmware: {
        controlBoard: ctrlBoardFw,
        controlBoardAux: ctrlBoardAuxFw,
        communicationBoard: commBoardFw,
        commBoardField1: commBoardFwField1,
        commBoardField2: commBoardFwField2
    },

    chipType: chipType,
    ratedPowerClass: ratedPowerClass,

    rawRegisters: data
};

const rpcResponseTopic = flow.get("invinfo_rpc_response_topic");
flow.set("invinfo_rpc_response_topic", null);

msg.payload = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;
